func:
let d = msg.payload || {};

let soil1 = Number(d.soil1_raw) || 0;
let soil2 = Number(d.soil2_raw) || 0;
let soilAvg = Number(d.soil_avg_raw) || 0;
let lux = Number(d.lux) || 0;
let uv = Number(d.uv_raw) || 0;
let temp = Number(d.temperature_c) || 0;
let hum = Number(d.humidity_pct) || 0;
let rssi = Number(d.wifi_rssi) || 0;

let threshold = Number(d.soil_dry_threshold) || 1500;
let soil1Dry = soil1 > threshold;
let soil2Dry = soil2 > threshold;
let necesitaRiego = soil1Dry || soil2Dry;

let soilEstado = "";
if (soil1Dry && soil2Dry) soilEstado = "🔴 Ambos sensores > " + threshold + ": requiere riego";
else if (soil1Dry) soilEstado = "🟠 Sensor 1 > " + threshold + ": requiere riego";
else if (soil2Dry) soilEstado = "🟠 Sensor 2 > " + threshold + ": requiere riego";
else soilEstado = "🟢 Suelo adecuado";

let luzEstado = "";
if (d.lux < 0 || d.lux === undefined || d.lux === null) luzEstado = "⚫ Sensor no disponible";
else if (lux < 50) luzEstado = "🔴 Muy oscuro";
else if (lux < 500) luzEstado = "🟡 Luz baja";
else if (lux < 3000) luzEstado = "🟢 Aceptable";
else luzEstado = "🟢 Buena luz";

let uvEstado = "";
if (uv < 300) uvEstado = "🟢 UV muy bajo";
else if (uv < 1000) uvEstado = "🟢 UV bajo";
else if (uv < 2000) uvEstado = "🟡 UV medio";
else uvEstado = "🔴 UV alto";

let riegoEstado = "";
if (d.modo_autonomo === true && necesitaRiego && d.pump_state === true) riegoEstado = "💧 Regando automáticamente";
else if (d.modo_autonomo === true && necesitaRiego && d.pump_state !== true) riegoEstado = "⏳ Requiere riego / esperando ciclo";
else if (d.modo_autonomo === true && !necesitaRiego) riegoEstado = "✅ Auto activo: sin riego";
else riegoEstado = "✋ Modo autónomo apagado";

return [
    {payload: soil1},
    {payload: soil2},
    {payload: soilAvg},
    {payload: lux},
    {payload: uv},
    {payload: temp},
    {payload: hum},
    {payload: soilEstado},
    {payload: luzEstado},
    {payload: uvEstado},
    {payload: rssi},
    {payload: d.pump_state ? 1 : 0},
    {payload: d.leds_state ? 1 : 0},
    {payload: d.modo_autonomo ? 1 : 0},
    {payload: soilAvg},
    {payload: lux},
    {payload: uv},
    {payload: temp},
    {payload: hum},
    {payload: d},
    {payload: riegoEstado}
];

let d = msg.payload;
msg.payload = d.status || JSON.stringify(d);
return msg;

let d = msg.payload || {};

function n(v, def=0) {
    let x = Number(v);
    return Number.isFinite(x) ? x : def;
}

let soilThr = n(d.soil_dry_threshold, 1500);
let luxThr = n(d.lux_low_threshold, 100);
let pumpOn = n(d.pump_on_time_ms, 3000);
let pumpCd = n(d.pump_cooldown_ms, 15000);
let nightMode = d.night_mode_enabled === true;
let nightStart = n(d.night_start_hour, 20);
let nightEnd = n(d.night_end_hour, 6);
let curHour = n(d.current_hour, 0);
let curMin = n(d.current_minute, 0);
let isNight = (d.is_night_time === true) || (d.night_time === true);
let blocked = d.leds_blocked_by_night === true;

flow.set("soil_dry_threshold", soilThr);
flow.set("lux_low_threshold", luxThr);
flow.set("pump_on_time_ms", pumpOn);
flow.set("pump_cooldown_ms", pumpCd);
flow.set("night_mode_enabled", nightMode);
flow.set("night_start_hour", nightStart);
flow.set("night_end_hour", nightEnd);
flow.set("current_hour", curHour);
flow.set("current_minute", curMin);

let hh = String(curHour).padStart(2, "0");
let mm = String(curMin).padStart(2, "0");

return [
  {payload: soilThr + " RAW"},
  {payload: luxThr + " lux"},
  {payload: pumpOn + " ms"},
  {payload: pumpCd + " ms"},
  {payload: nightMode ? "ON" : "OFF"},
  {payload: nightStart + ":00 → " + nightEnd + ":00"},
  {payload: hh + ":" + mm},
  {payload: isNight ? "Sí" : "No"},
  {payload: blocked ? "Sí" : "No"},

  // Salidas 9-17: sincronizan los controles editables del dashboard.
  {payload: soilThr},
  {payload: luxThr},
  {payload: pumpOn},
  {payload: pumpCd},
  {payload: curHour},
  {payload: curMin},
  {payload: nightStart},
  {payload: nightEnd},
  {payload: nightMode}
];

let topic = msg.topic || "";

function num(name, def) {
    let v = Number(flow.get(name));
    return Number.isFinite(v) ? v : def;
}

function boolv(name, def) {
    let v = flow.get(name);
    if (v === undefined || v === null || v === "") return def;
    return v === true || v === "true" || v === 1 || v === "1";
}

function buildConfigPayload() {
    return {
        cmd: "SET_CONFIG",
        soil_dry_threshold: num("soil_dry_threshold", 1500),
        lux_low_threshold: num("lux_low_threshold", 100),
        pump_on_time_ms: num("pump_on_time_ms", 3000),
        pump_cooldown_ms: num("pump_cooldown_ms", 15000),
        night_mode_enabled: boolv("night_mode_enabled", true),
        night_start_hour: num("night_start_hour", 20),
        night_end_hour: num("night_end_hour", 6),
        current_hour: num("current_hour", 12),
        current_minute: num("current_minute", 0)
    };
}

// Actualizar valores en memoria de flujo desde inputs.
if (topic && topic !== "save_config") {
    flow.set(topic, msg.payload);
    node.status({fill:"blue", shape:"dot", text: topic + "=" + msg.payload});

    // El interruptor de modo noche se envía inmediatamente para que la app
    // y Node-RED queden sincronizados a través de la telemetría del ESP32.
    if (topic !== "night_mode_enabled") {
        return null;
    }
}

msg.topic = "agrihome/cmd";
msg.payload = JSON.stringify(buildConfigPayload());
node.status({fill:"green", shape:"dot", text:"SET_CONFIG enviado"});
return msg;

let d = msg.payload || {};

function csvEscape(v) {
    if (v === undefined || v === null) return "";
    let s = String(v);
    if (s.includes('"') || s.includes(',') || s.includes('\n') || s.includes('\r')) {
        return '"' + s.replace(/"/g, '""') + '"';
    }
    return s;
}

let timestamp = new Date().toISOString();

let columns = [
    "timestamp_iso",
    "soil1_raw",
    "soil2_raw",
    "soil_avg_raw",
    "lux",
    "uv_raw",
    "temperature_c",
    "humidity_pct",
    "pump_state",
    "leds_state",
    "modo_autonomo",
    "soil1_dry",
    "soil2_dry",
    "any_soil_dry",
    "low_light",
    "auto_pump_running",
    "soil_dry_threshold",
    "lux_low_threshold",
    "pump_on_time_ms",
    "pump_cooldown_ms",
    "current_hour",
    "current_minute",
    "night_mode_enabled",
    "night_start_hour",
    "night_end_hour",
    "night_time",
    "leds_blocked_by_night",
    "wifi_rssi",
    "mqtt_connected",
    "ble_connected",
    "uptime_ms"
];

let values = [
    timestamp,
    d.soil1_raw,
    d.soil2_raw,
    d.soil_avg_raw,
    d.lux,
    d.uv_raw,
    d.temperature_c,
    d.humidity_pct,
    d.pump_state,
    d.leds_state,
    d.modo_autonomo,
    d.soil1_dry,
    d.soil2_dry,
    d.any_soil_dry,
    d.low_light,
    d.auto_pump_running,
    d.soil_dry_threshold,
    d.lux_low_threshold,
    d.pump_on_time_ms,
    d.pump_cooldown_ms,
    d.current_hour,
    d.current_minute,
    d.night_mode_enabled,
    d.night_start_hour,
    d.night_end_hour,
    (d.night_time === true || d.is_night_time === true),
    d.leds_blocked_by_night,
    d.wifi_rssi,
    d.mqtt_connected,
    d.ble_connected,
    d.uptime_ms
];

let headerNeeded = flow.get("agrihome_csv_header_written") !== true;
let header = columns.join(",") + "\n";
let line = values.map(csvEscape).join(",") + "\n";

if (headerNeeded) {
    flow.set("agrihome_csv_header_written", true);
}

let csvMsg = {
    payload: (headerNeeded ? header : "") + line
};

let statusMsg = {
    payload: "Registro CSV agregado: " + timestamp
};

return [csvMsg, statusMsg];

flow.set("agrihome_csv_header_written", false);
msg.payload = "El siguiente registro CSV incluirá encabezado.";
return msg;
